-- Cadastro idempotente: Conexão Equestre → projeto "Novo site Conexão Equestre" → vínculo Maisis.
-- Gerado por build-sql.mjs a partir de conexao-equestre.json. Não cria usuários Auth nem memberships.
begin;
select pg_advisory_xact_lock(hashtext('onboard:conexao-equestre'));
do $onboard$
declare cid uuid; pid uuid; aid uuid; tid uuid; payload jsonb := '{"roadmap":{"stack":{"architecture":{"title":"A tecnologia do novo site.","description":"Pacote Básico: site de página única, estático e rápido, com todo o conteúdo atual reorganizado. Os pacotes Completo e Plataforma adicionam painel de edição, agenda e inscrições sobre esta mesma base.","inputs":[{"id":"site","brand":"","title":"Site de página única","tool":"HTML, CSS e JavaScript","detail":"Seções âncora, menu dos quatro grupos e blocos expansíveis","href":"https://developer.mozilla.org/pt-BR/docs/Web/HTML"},{"id":"whatsapp","brand":"whatsapp","title":"Contato pelo WhatsApp","tool":"WhatsApp Business","detail":"Botão fixo e formulário que abre a conversa preenchida","href":"https://business.whatsapp.com"},{"id":"mapa","brand":"googlemaps","title":"Mapa da sede","tool":"Google Maps","detail":"Localização e rota incorporadas","href":"https://www.google.com/maps"},{"id":"videos","brand":"youtube","title":"Vídeos dos cursos","tool":"YouTube","detail":"Canal da Conexão incorporado","href":"https://www.youtube.com/channel/UCHqiBuZ6-DypOSmTP8HOPBA"}],"core":{"id":"core","brand":"no","title":"Site publicado pela nó","tool":"Vercel","detail":"Hospedagem em CDN com HTTPS · prevista para o site final","href":"https://vercel.com"},"services":[{"id":"dominio","brand":"hostinger","title":"Domínio e e-mail","tool":"Hostinger","detail":"conexaoequestre.com.br apontado para o novo site · após aprovação","href":"https://www.hostinger.com.br"},{"id":"seo","brand":"meta","title":"SEO básico e compartilhamento","tool":"Meta tags + Open Graph","detail":"Título, descrição e prévia ao compartilhar no WhatsApp, Instagram e Facebook","href":"https://developers.facebook.com/docs/sharing/webmasters/"},{"id":"painel","brand":"supabase","title":"Painel de edição","tool":"Supabase","detail":"Somente nos pacotes Completo e Plataforma","href":"https://supabase.com"}],"caption":"O protótipo navegável é o Pacote Básico pronto para aprovação. Hospedagem, domínio e painel dependem do pacote escolhido e ainda não foram ativados."}},"costs":[],"next_steps":{"presentation":{"phase_mode":"source","review_label":"Proposta em análise","review_description":"Três pacotes apresentados pela Maisis. Nenhum aprovado ainda.","prototype_title":"Navegue pelo novo site.","editor_lock_reason":"O Editor fica bloqueado até a aprovação do pacote. Navegue pela aba Protótipo e envie suas observações à Maisis.","hero_title":"O novo site da Conexão Equestre, pronto para aprovação.","hero_description":"Explore o protótipo do site de página única, conheça a tecnologia e compare os três pacotes propostos.","infrastructure_title":"Três pacotes. Escolha o tamanho do próximo passo.","scope_options":[{"label":"Básico","badge":"Pacote 1","price":"R$ 2 mil","tagline":"O site que você está vendo no protótipo, pronto para ir ao ar.","selected":false,"features":["Site novo em uma página, com todo o conteúdo atual organizado e leve.","Botão de WhatsApp, mapa e vídeos do YouTube.","Visual limpo, sem animações.","Pronto em 1 a 2 semanas · 15 dias de suporte."],"cta_label":"Quero o Básico","cta_href":"mailto:contato@maisispublicidade.com.br?subject=Conex%C3%A3o%20Equestre%20-%20Pacote%20B%C3%A1sico"},{"label":"Completo","badge":"Pacote 2","price":"R$ 5 mil","tagline":"Site completo que a própria equipe da Conexão atualiza.","selected":false,"features":["Uma página para cada curso, serviço e evento.","Painel simples para trocar textos, fotos, datas e valores sem programador.","Agenda de cursos e eventos, galeria de fotos e animações suaves.","Pronto em 3 a 5 semanas · 30 dias de suporte."],"cta_label":"Quero o Completo","cta_href":"mailto:contato@maisispublicidade.com.br?subject=Conex%C3%A3o%20Equestre%20-%20Pacote%20Completo"},{"label":"Plataforma","badge":"Pacote 3","price":"R$ 10 mil","tagline":"Inscrições e pagamentos direto pelo site.","selected":false,"features":["Inscrição em cursos e passeios com Pix e cartão, vagas e confirmação automática.","Área do aluno e ficha do cavalo hospedado para os proprietários.","Blog, newsletter, versão em inglês e experiência premium com transições e componentes interativos.","Pronto em 6 a 9 semanas · 60 dias de suporte."],"cta_label":"Quero a Plataforma","cta_href":"mailto:contato@maisispublicidade.com.br?subject=Conex%C3%A3o%20Equestre%20-%20Pacote%20Plataforma"}],"scope_note":"Nenhum pacote foi escolhido ainda. Os valores são da proposta de 20/10/2026; custos de domínio, e-mail e meio de pagamento são confirmados por pacote antes do fechamento. Prazos são estimativas.","hide_project_navigation":true},"task_details":{}},"references":["Site atual: https://conexaoequestre.com.br/ (20 páginas levantadas em 20/10/2026)","Proposta: app/onboarding/conexao-equestre/PROPOSTA-PACOTES.md","Protótipo: lp-basica-v1 (Pacote Básico)"],"tiers":{},"preferred_tier":null,"prototype_url":"/prototipos/conexao-equestre/lp-basica-v1/index.html"},"tasks":[{"source_id":"p0-1","title":"Levantamento do site atual","phase":"Fase 0 · Proposta","status":"concluido","note":"20 páginas do WordPress lidas: textos, menu, equipe, contatos e fotos.","week":1,"position":0},{"source_id":"p0-2","title":"Proposta com três pacotes","phase":"Fase 0 · Proposta","status":"concluido","note":"Básico, Completo e Plataforma, com prazos e suporte.","week":1,"position":1},{"source_id":"p0-3","title":"Protótipo do Pacote Básico","phase":"Fase 0 · Proposta","status":"concluido","note":"Disponível na aba Protótipo.","week":1,"position":2},{"source_id":"p0-4","title":"Apresentação pela Maisis","phase":"Fase 0 · Proposta","status":"a_fazer","note":"Reunião com a Conexão Equestre.","week":2,"position":3},{"source_id":"p0-5","title":"Escolha do pacote","phase":"Fase 0 · Proposta","status":"a_fazer","note":"Define o escopo das próximas fases.","week":2,"position":4},{"source_id":"p1-1","title":"Revisão dos textos de cada seção","phase":"Fase 1 · Reforma de identidade","status":"a_fazer","note":"Cursos, horários, datas e valores desatualizados; avisos de 2022 e 2023 removidos.","week":3,"position":5},{"source_id":"p1-2","title":"Troca das imagens","phase":"Fase 1 · Reforma de identidade","status":"a_fazer","note":"Hero, cards e galeria com fotos novas enviadas pela Conexão.","week":3,"position":6},{"source_id":"p1-3","title":"Atualização da equipe e contatos","phase":"Fase 1 · Reforma de identidade","status":"a_fazer","note":"Nomes, funções, fotos, telefone e redes sociais.","week":3,"position":7},{"source_id":"p1-4","title":"Logo e cores no novo layout","phase":"Fase 1 · Reforma de identidade","status":"a_fazer","note":"Verde e âmbar do logo aplicados em todo o site.","week":3,"position":8},{"source_id":"p2-1","title":"Ajustes após a aprovação","phase":"Fase 2 · Produção do site","status":"a_fazer","note":"Rodadas de revisão conforme o pacote.","week":4,"position":9},{"source_id":"p2-2","title":"Domínio, hospedagem e redirecionamentos","phase":"Fase 2 · Produção do site","status":"a_fazer","note":"conexaoequestre.com.br apontado; URLs antigas levam às seções.","week":4,"position":10},{"source_id":"p2-3","title":"Testes em celular e computador","phase":"Fase 2 · Produção do site","status":"a_fazer","note":"Velocidade, formulário, WhatsApp e mapa.","week":5,"position":11},{"source_id":"p3-1","title":"Site no ar e WordPress desligado","phase":"Fase 3 · Publicação","status":"a_fazer","note":"Após os testes finais.","week":5,"position":12},{"source_id":"p3-2","title":"Início do suporte","phase":"Fase 3 · Publicação","status":"a_fazer","note":"Período conforme o pacote escolhido.","week":6,"position":13}]}'::jsonb; task jsonb; details jsonb := '{}'::jsonb;
begin
  select id into aid from public.agencies where slug='maisis';
  if aid is null then raise exception 'Agency % not found', 'maisis'; end if;
  if not exists(select 1 from public.agencies where id=aid and name='Maisis Publicidade' and active) then raise exception 'Agency identity/status mismatch'; end if;
  select id into cid from public.clients where slug='conexao-equestre';
  if cid is null then
    if exists(select 1 from public.clients where name ilike '%conex%' or name ilike '%equestre%') then raise exception 'Review existing similar client'; end if;
    insert into public.clients(name,slug) values('Conexão Equestre','conexao-equestre') returning id into cid;
  elsif not exists(select 1 from public.clients where id=cid and name='Conexão Equestre') then raise exception 'Client identity mismatch'; end if;
  if (select count(*) from public.projects where client_id=cid and name='Novo site Conexão Equestre')>1 then raise exception 'Duplicate project'; end if;
  select id into pid from public.projects where client_id=cid and name='Novo site Conexão Equestre';
  if pid is null then
    insert into public.projects(client_id,name,niche,lead_status,project_status,modules)
    values(cid,'Novo site Conexão Equestre','centro hípico · Bragança Paulista','JANELA_DE_DECISAO','EM_REVISAO_CLIENTE','{"como_funciona":"ativo","prototipo":"ativo","etapas":"ativo","editor":"bloqueado","versoes":"bloqueado","marca":"bloqueado"}'::jsonb) returning id into pid;
  else
    update public.projects set niche='centro hípico · Bragança Paulista',project_status='EM_REVISAO_CLIENTE',modules=modules || '{"como_funciona":"ativo","prototipo":"ativo","etapas":"ativo","editor":"bloqueado","versoes":"bloqueado","marca":"bloqueado"}'::jsonb where id=pid;
  end if;
  if exists(select 1 from public.agency_projects where project_id=pid and agency_id<>aid) then raise exception 'Project already assigned to another agency'; end if;
  insert into public.agency_projects(agency_id,project_id) values(aid,pid) on conflict(project_id) do nothing;
  for task in select value from jsonb_array_elements(payload->'tasks') loop
    tid := null;
    select k.id into tid from public.kanban_items k where k.project_id=pid and k.title=task->>'title';
    if tid is null then
      insert into public.kanban_items(project_id,title,phase,status,position)
      values(pid,task->>'title',task->>'phase',(task->>'status')::public.kanban_status,(task->>'position')::integer) returning id into tid;
    else
      update public.kanban_items set phase=task->>'phase',status=(task->>'status')::public.kanban_status,position=(task->>'position')::integer where id=tid;
    end if;
    details := details || jsonb_build_object(tid::text,jsonb_build_object('source_id',task->>'source_id','note',task->>'note','week',task->'week'));
  end loop;
  insert into public.roadmaps(project_id,stack,costs,next_steps,"references",tiers,prototype_url,published_at)
  values(pid,payload->'roadmap'->'stack',payload->'roadmap'->'costs',(payload->'roadmap'->'next_steps') || jsonb_build_object('task_details',details),payload->'roadmap'->'references','{}',payload->'roadmap'->>'prototype_url',now())
  on conflict(project_id) do update set stack=excluded.stack,costs=excluded.costs,next_steps=excluded.next_steps,"references"=excluded."references",prototype_url=excluded.prototype_url,published_at=coalesce(roadmaps.published_at,excluded.published_at);
end $onboard$;
commit;
select c.id client_id,p.id project_id,a.id agency_id,c.name,p.lead_status,p.project_status,p.modules,r.prototype_url,
(select count(*) from public.kanban_items where project_id=p.id) tasks,
(select count(*) from public.kanban_items where project_id=p.id and status='concluido') completed,
(select count(*) from public.memberships where client_id=c.id) client_memberships
from public.clients c join public.projects p on p.client_id=c.id join public.agency_projects ap on ap.project_id=p.id join public.agencies a on a.id=ap.agency_id join public.roadmaps r on r.project_id=p.id where c.slug='conexao-equestre';
